def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find rectangular outlines with a uniform interior, and color their holes.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    color = g[r1][c1]
                    if any(g[r1][c] != color or g[r2][c] != color
                           for c in range(c1, c2 + 1)):
                        continue
                    if any(g[r][c1] != color or g[r][c2] != color
                           for r in range(r1, r2 + 1)):
                        continue
                    inside = [g[r][c] for r in range(r1 + 1, r2)
                              for c in range(c1 + 1, c2)]
                    if inside and len(set(inside)) == 1 and inside[0] != color:
                        fill = 2 if (r2 - r1 == 3 and c2 - c1 == 3) else 7
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                g[r][c] = fill
    return g
